import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CvydjLy7.js";const _=JSON.parse('{"title":"11.10 问题速查","description":"","frontmatter":{"title":"11.10 问题速查"},"headers":[],"relativePath":"ch11/10.md","filePath":"ch11/10.md","lastUpdated":1789497795000}'),r={name:"ch11/10.md"};function a(n,t,i,l,s,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="_11-10-问题速查" tabindex="-1">11.10 问题速查 <a class="header-anchor" href="#_11-10-问题速查" aria-label="Permalink to &quot;11.10 问题速查&quot;">​</a></h1><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td><code>java -jar</code> 报“没有主清单属性”</td><td>拿到的是 <code>.jar.original</code></td><td>检查 jar 的 MANIFEST 里有没有 <code>Spring-Boot-Version</code></td></tr><tr><td><code>-Djarmode=layertools</code> 报 jarmode 不认识</td><td>4.x 已改名</td><td>换成 <code>-Djarmode=tools</code></td></tr><tr><td><code>extract</code> 出的 <code>spring-boot-loader</code> 是空目录</td><td><code>--layers</code> 默认不带启动器</td><td>需要启动器时加 <code>--launcher</code></td></tr><tr><td>解压后 <code>java -jar</code> 报找不到类</td><td>各层没拼到同一个目录</td><td>把四层内容都拷进同一工作目录</td></tr><tr><td>薄 jar 的 <code>Class-Path</code> 指向的 lib 找不到</td><td>同上，<code>lib/</code> 必须与 jar 同级</td><td>检查目录结构</td></tr><tr><td><code>.jsa</code> 挂上去启动没变化</td><td>用的是可执行 jar</td><td>CDS 只对解压形态生效</td></tr><tr><td><code>.jsa</code> 拷到别的机器上报错</td><td>归档与平台、JDK 版本绑定</td><td>在目标平台重新做训练运行</td></tr><tr><td>镜像比预期大 60 多 MB</td><td><code>COPY</code> 之后又用了 <code>RUN chown</code></td><td>改成 <code>COPY --chown</code></td></tr><tr><td>训练运行让镜像多出上百 MB</td><td>CDS 归档本身就有 100MB 量级</td><td>评估启动收益是否值得这个体积</td></tr><tr><td>非 root 用户启动后写文件失败</td><td>工作目录或子目录属主是 root</td><td>建目录时一并 <code>chown</code>，或把可变数据挂卷</td></tr><tr><td><code>chown</code> 之后文件属主还是 root</td><td>写在了 <code>COPY</code> 之前</td><td><code>COPY --chown</code> 必须和 <code>COPY</code> 在同一条指令里</td></tr><tr><td>源码没变但镜像每次都要重建</td><td>jar 的时间戳变了</td><td>分层写法可让依赖层命中缓存；必要时 <code>--no-cache</code></td></tr><tr><td><code>-Dspring.aot.enabled=true</code> 后启动失败</td><td>用了 AOT 不支持的运行期条件装配</td><td>检查 <code>@ConditionalOnProperty</code> 与 profile 相关 Bean</td></tr><tr><td>打了 <code>-Pnative</code> 但没变快</td><td>只跑了 <code>package</code>，AOT 代码没被启用</td><td>运行时加 <code>-Dspring.aot.enabled=true</code></td></tr><tr><td><code>mvn -Pnative package</code> 没产出可执行文件</td><td><code>native:compile</code> 不绑定在 <code>package</code> 阶段</td><td>显式加上 <code>native:compile</code></td></tr><tr><td>原生编译报缺少反射配置</td><td><code>--no-fallback</code> 加提示文件不全</td><td>补 <code>@RegisterReflectionForBinding</code> 或自定义 hint</td></tr><tr><td>原生镜像里 profile 不生效</td><td>封闭世界假设，Bean 定义构建期定死</td><td>改成用配置值区分，而不是用 profile 区分装配</td></tr><tr><td>容器堆内存只有限制的 1/4</td><td><code>MaxRAMPercentage</code> 默认 25%</td><td><code>JAVA_TOOL_OPTIONS=-XX:MaxRAMPercentage=75</code></td></tr><tr><td>改了环境变量配置没生效</td><td>名字没规范化</td><td>点转下划线、去掉连字符、全大写</td></tr><tr><td><code>docker stop</code> 时请求被切断</td><td>没开优雅停机</td><td><code>server.shutdown=graceful</code></td></tr><tr><td>buildpacks 构建报 builder 不可信</td><td>用了非官方 builder</td><td>显式设 <code>trustBuilder</code>，或改用官方 builder</td></tr></tbody></table><hr>',3)])])}const u=d(r,[["render",a]]);export{_ as __pageData,u as default};
